import{z as s,x as o,o as l,c as d,q as i,j as A,D as e,d as t,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"批处理与调度","description":"","frontmatter":{"title":"批处理与调度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-batching-scheduling.md","filePath":"llm/diff-batching-scheduling.md","lastUpdated":1791063341000}'),p={name:"llm/diff-batching-scheduling.md"};function D(h,E,c,m,u,F){const B=o("Mermaid");return l(),d("div",null,[E[2]||(E[2]=i('<h1 id="批处理与调度" tabindex="-1">批处理与调度 <a class="header-anchor" href="#批处理与调度" aria-label="Permalink to &quot;批处理与调度&quot;">​</a></h1><div class="epigraph"><p>LLM 的连续批处理逐 token 插人，扩散的批只在步与步之间同进同退；把自回归的调度直觉搬过来，凑出来的批会互相拖死。</p><footer>—— 据 Yu 等 Orca 的迭代级调度与扩散服务实现对照整理</footer></div><p><a href="/llm/diff-quantization">上一课</a>把单次前向跑便宜，本课把并行度补上：批与调度。请求调度的基础与指标、连续批处理的机制在<a href="/llm/sch-basics-metrics">调度课</a>与<a href="/llm/sch-continuous-batching-deep">连续批处理深入</a>已立；本课只写扩散侧的差异：没有逐 token 的增量结构，却有逐请求固定的形状与步数，调度器因此长成另一种形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩散请求在进队时就带着完整规格：分辨率、步数、引导、条件。这给了调度器 LLM 没有的先见——每个请求的总前向次数已知，队列长度可以精确折算成 GPU 时间；也拿走了 LLM 有的自由——批内所有请求必须同形状、同步数地走完每一步，中途无法像 Orca 那样在迭代边界插入新请求再按需重算。缺口是把这两个约束写成调度协议：怎么分桶、怎么凑批、怎么不让一张 \\(1024\\times1024\\) 的请求把一整批 \\(512\\) 的拖进 OOM 或重编译。</p><p><span class="marginnote">「分桶」翻译一下：把分辨率和步数相同的请求装进同一个筐再一起算。桶像公交线路——按「路线」（形状）发车，不按乘客身份（优先级）发车；同一线路凑满一车最省油，硬把不同路线的乘客塞一车，人人都得绕路。</span></p><h3 id="形状是第一维度" tabindex="-1">形状是第一维度 <a class="header-anchor" href="#形状是第一维度" aria-label="Permalink to &quot;形状是第一维度&quot;">​</a></h3><p>批的第一个维度不是优先级而是形状。注意力与卷积核按形状编译或图捕获，形状一变就触发重编译或退化到通用核；激活显存随批大小 × 潜变量面积线性涨。所以生产做法是按（分辨率，步数）分桶：桶内凑批，桶间排队；分辨率翻倍，token 数变四倍，注意力 FLOPs 变十六倍，高分辨率桶天然要小批。把不同分辨率硬凑进一个批，结果是 padding 浪费加显存尖峰，两头都亏。</p><p><span class="marginnote">512→1024 使潜变量 token 数 ×4、注意力 FLOPs ×16。容量规划时高分辨率请求不能按像素面积折算成本，要按注意力平方项折算——这是扩散调度最常被低估的一项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调度器四层：</p><ul><li><strong>分桶层</strong>：按（分辨率，步数）分桶；桶是编译与显存的单位，不是策略的单位。</li><li><strong>凑批层</strong>：桶内积批，批大小由显存水位与延迟目标共同给出；交互流量留一个小的常驻批位，离线流量填满剩余。</li><li><strong>优先级层</strong>：交互请求与离线请求分队列；离线批可以跑到步中再让出吗——不可以，让出点只能是批边界，因此离线批的批大小要设上限，避免长批把交互队列饿死。</li><li><strong>溢出层</strong>：显存水位超限时先降批再降分辨率，最后才是拒绝；每一步降级都要在指标里留痕。</li></ul><p><span class="marginnote">降级顺序有讲究：先降批大小，用户完全无感，只是排队的人多等一会儿；再降分辨率，输出尺寸变了，用户看得见。所以「先降批再降分辨率」本质是先花看不见的成本，再花看得见的成本——顺序反了，投诉先来。</span></p>',13)),(l(),A(n,null,{default:e(()=>[r(B,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E5%88%86%E8%BE%A8%E7%8E%87%2B%E6%AD%A5%E6%95%B0%2B%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%20--%3E%20BKT%5B%22%E5%88%86%E6%A1%B6%EF%BC%9A%E5%88%86%E8%BE%A8%E7%8E%87%20%C3%97%20%E6%AD%A5%E6%95%B0%22%5D%0A%20%20BKT%20--%3E%20Q1%5B%22%E4%BA%A4%E4%BA%92%E9%98%9F%E5%88%97%22%5D%0A%20%20BKT%20--%3E%20Q2%5B%22%E7%A6%BB%E7%BA%BF%E9%98%9F%E5%88%97%22%5D%0A%20%20Q1%20--%3E%20BAT%5B%22%E6%A1%B6%E5%86%85%E5%87%91%E6%89%B9%EF%BC%9A%E6%98%BE%E5%AD%98%E6%B0%B4%E4%BD%8D%E5%86%85%22%5D%0A%20%20Q2%20--%3E%20BAT%0A%20%20BAT%20--%3E%20LOOP%5B%22%E6%AD%A5%E8%BF%9B%E5%BE%AA%E7%8E%AF%EF%BC%9A%E6%89%B9%E5%86%85%E5%90%8C%E8%BF%9B%E5%90%8C%E9%80%80%22%5D%0A%20%20LOOP%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%87%BA%E5%9B%BE%EF%BC%8C%E6%89%B9%E4%BD%8D%E9%87%8A%E6%94%BE%22%5D%0A%20%20DEC%20--%3E%20BAT%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"为什么中途不能插入新请求：Orca 的迭代级调度依赖「每步只算一个 token、序列可随时重排」；扩散每步对整批潜变量张量做全量计算，批是张量的形状而不是集合的容量，插入意味着重排张量与重算掩码，成本超过等待。可让渡的粒度因此是「批边界」：一个请求出图、批位释放，新请求才能进。这决定了交互延迟的下限是当前批的剩余步数 × 单步时延——调度器能做的是把交互请求放进小批快桶，而不是许诺随时插队。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字感受一下延迟下限：30 步日程、单步 40 毫秒，一张图的批要跑 1.2 秒。交互请求若恰好排在刚开跑的大批后面，最坏要等满 1.2 秒才有批位空出。这就是给交互流量留「小批快桶」的原因——不是让它插队，而是让它上一辆开得快的车。")],-1)),(l(),A(n,null,{default:e(()=>[r(B,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20LLM%5B%22LLM%20%E8%BF%9E%E7%BB%AD%E6%89%B9%E5%A4%84%E7%90%86%22%5D%0A%20%20%20%20L1%5B%22%E6%AF%8F%E6%AD%A5%E6%AF%8F%E5%BA%8F%E5%88%97%E5%8F%AA%E7%AE%97%E4%B8%80%E4%B8%AA%20token%22%5D%20--%3E%20L2%5B%22%E8%BF%AD%E4%BB%A3%E8%BE%B9%E7%95%8C%E5%8F%AF%E9%9A%8F%E6%97%B6%E9%87%8D%E6%8E%92%E6%89%B9%22%5D%0A%20%20%20%20L2%20--%3E%20L3%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%E6%9D%A5%E4%BA%86%E5%B0%B1%E6%8F%92%E5%85%A5%22%5D%0A%20%20end%0A%20%20subgraph%20DIF%5B%22%E6%89%A9%E6%95%A3%E6%89%B9%22%5D%0A%20%20%20%20D1%5B%22%E6%AF%8F%E6%AD%A5%E7%AE%97%E6%95%B4%E6%89%B9%E6%BD%9C%E5%8F%98%E9%87%8F%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20D2%5B%22%E6%89%B9%20%3D%20%E5%BC%A0%E9%87%8F%E5%BD%A2%E7%8A%B6%3Cbr%2F%3E%E6%8F%92%E5%85%A5%E8%A6%81%E9%87%8D%E6%8E%92%E4%B8%8E%E9%87%8D%E7%AE%97%E6%8E%A9%E7%A0%81%22%5D%0A%20%20%20%20D2%20--%3E%20D3%5B%22%E5%8F%AA%E8%83%BD%E7%AD%89%E6%89%B9%E8%BE%B9%E7%95%8C%E6%94%BE%E4%BA%BA%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p>为什么先见反而简化调度：步数与形状在进队时已知，每请求的前向次数可静态折算，队列时延预估可以做到相当准；LLM 调度「输出长度未知」的估计噪声在扩散侧消失。代价是用户改配置就改负载：产品把步数与分辨率开放给用户时，等于把桶的基数开放出去，桶数爆炸会让凑批率掉光——产品层要收敛到几个预设档位，这是调度协议伸进产品设计的部分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假设同模型同版本的单实例；多模型并存的换入换出是成本课的题材。批内请求共享同一日程，个体提前终止（如步中安全拦截）要么等批结束再裁，要么引入掩码开销，两种都算进账。与传统 LLM 调度的对照到此为止：KV 驱动的抢占与换入换出在扩散侧没有对应物，不要为了对称而引入。批大小与时延的曲线要在自己的硬件上实测，纸面 FLOPs 折算不可用——评测口径见本课程后面的评测课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扩散请求进队时规格完备：总前向次数已知，但批必须同形状同步数同进同退。</li><li>调度第一维是形状：按（分辨率，步数）分桶，桶绑定编译与显存预算。</li><li>Orca 式迭代级插人不适用，让渡粒度是批边界；交互延迟下限由当前批剩余步数决定。</li><li>高分辨率按注意力平方项折算成本，不按像素面积。</li><li>产品档位收敛桶数：开放全部分辨率与步数等于开放调度器的坟墓。</li><li>出处：Yu 等 Orca（OSDI 2022）的迭代级调度对照；桶协议据扩散服务实践整理。</li></ul>',5))])}const b=s(p,[["render",D]]);export{g as __pageData,b as default};
